import { cn } from "@/lib/utils"

/**
 * Total Wireless Phone Option Card Component
 *
 * Used on the "Choose your phone" page. Options include:
 * - Bring your own phone (no image)
 * - Specific phone models with "Special Offer" badge
 * - "Shop all new phones" link card
 *
 * Based on the phone selection UI from the desktop shopping flow.
 *
 * Usage:
 * <PhoneOption selected>
 *   <PhoneOptionBadge>Special Offer</PhoneOptionBadge>
 *   <PhoneOptionContent>
 *     <PhoneOptionTitle>Samsung Galaxy A37 5G</PhoneOptionTitle>
 *     <PhoneOptionDescription>Great value smartphone</PhoneOptionDescription>
 *   </PhoneOptionContent>
 *   <PhoneOptionImage src="/phone.png" alt="Samsung Galaxy A37" />
 * </PhoneOption>
 */

interface PhoneOptionProps extends React.HTMLAttributes<HTMLDivElement> {
  selected?: boolean
}

function PhoneOption({
  className,
  selected,
  children,
  ...props
}: PhoneOptionProps) {
  return (
    <div
      data-slot="phone-option"
      data-selected={selected ? "" : undefined}
      className={cn(
        "relative flex items-center gap-4 rounded-xl border-2 px-5 py-4 transition-all cursor-pointer",
        selected
          ? "border-tw-navy-900 bg-tw-navy-50 shadow-[0_0_0_3px_rgba(0,3,48,0.12)]"
          : "border-tw-gray-200 bg-white hover:border-tw-gray-300 hover:shadow-[var(--shadow-card)]",
        className
      )}
      {...props}
    >
      {children}
    </div>
  )
}

function PhoneOptionBadge({
  className,
  children,
  ...props
}: React.HTMLAttributes<HTMLSpanElement>) {
  return (
    <span
      data-slot="phone-option-badge"
      className={cn(
        "absolute -top-2.5 left-4 inline-flex items-center rounded-md bg-tw-teal-400 px-2.5 py-0.5 text-xs font-semibold text-tw-navy-900",
        className
      )}
      {...props}
    >
      {children}
    </span>
  )
}

function PhoneOptionContent({
  className,
  children,
  ...props
}: React.HTMLAttributes<HTMLDivElement>) {
  return (
    <div
      data-slot="phone-option-content"
      className={cn("flex-1 min-w-0", className)}
      {...props}
    >
      {children}
    </div>
  )
}

function PhoneOptionTitle({
  className,
  children,
  ...props
}: React.HTMLAttributes<HTMLHeadingElement>) {
  return (
    <h4
      data-slot="phone-option-title"
      className={cn(
        "text-base font-bold text-tw-navy-900 leading-tight",
        className
      )}
      {...props}
    >
      {children}
    </h4>
  )
}

function PhoneOptionDescription({
  className,
  children,
  ...props
}: React.HTMLAttributes<HTMLParagraphElement>) {
  return (
    <p
      data-slot="phone-option-description"
      className={cn("text-sm text-tw-gray-500 mt-0.5", className)}
      {...props}
    >
      {children}
    </p>
  )
}

function PhoneOptionImage({
  className,
  src,
  alt,
  ...props
}: React.ImgHTMLAttributes<HTMLImageElement>) {
  return (
    <div className="flex-shrink-0 w-12 h-12 flex items-center justify-center">
      {/* eslint-disable-next-line @next/next/no-img-element */}
      <img
        data-slot="phone-option-image"
        className={cn("max-w-full max-h-full object-contain", className)}
        src={src}
        alt={alt || ""}
        {...props}
      />
    </div>
  )
}

function PhoneOptionArrow({ className, ...props }: React.HTMLAttributes<HTMLDivElement>) {
  return (
    <div
      data-slot="phone-option-arrow"
      className={cn("flex-shrink-0 text-tw-gray-400", className)}
      {...props}
    >
      <svg
        className="h-5 w-5"
        fill="none"
        viewBox="0 0 24 24"
        strokeWidth={2}
        stroke="currentColor"
      >
        <path
          strokeLinecap="round"
          strokeLinejoin="round"
          d="M8.25 4.5l7.5 7.5-7.5 7.5"
        />
      </svg>
    </div>
  )
}

export {
  PhoneOption,
  PhoneOptionBadge,
  PhoneOptionContent,
  PhoneOptionTitle,
  PhoneOptionDescription,
  PhoneOptionImage,
  PhoneOptionArrow,
}
